/* Extracted from the customer workflow; existing business globals and stored records stay compatible. */
'use strict';
const MOBILE_PREVIEW_TABS=[['mobile-approvals','移动核查'],['mobile-customer','门店工作台'],['mobile-store','移动档案工作台']];
let mobilePreviewFocus=false;
function mobilePreviewCurrent(){return route==='mobile-store'?'mobile-store':['mobile-customer','mobile-new'].includes(route)?'mobile-customer':'mobile-approvals'}
function mobilePreviewTabs(){
 if(!route.startsWith('mobile')||new URLSearchParams(location.search).get('view')==='h5')return '';
 return pageTabs(MOBILE_PREVIEW_TABS.map(([key,label])=>[key,label,`switchMobilePreview('${key}')`]),mobilePreviewCurrent(),'移动端预览')
  .replace('class="page-tabs"','class="page-tabs mobile-preview-tabs"')
  .replace(/aria-selected="(true|false)"/g,(_,selected)=>`aria-selected="${selected}" tabindex="${selected==='true'?0:-1}"`);
}
function switchMobilePreview(next,focus=false){
 if(!MOBILE_PREVIEW_TABS.some(([key])=>key===next)||next===mobilePreviewCurrent())return;
 mobilePreviewFocus=focus;go(next);
}
function restoreMobilePreviewFocus(){
 if(!mobilePreviewFocus)return;
 document.querySelector('.mobile-preview-tabs [aria-selected="true"]')?.focus({preventScroll:true});mobilePreviewFocus=false;
}
document.addEventListener('keydown',event=>{
 const tab=event.target.closest?.('.mobile-preview-tabs [role=tab]');
 if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;
 event.preventDefault();
 const index=MOBILE_PREVIEW_TABS.findIndex(([key])=>key===mobilePreviewCurrent()),length=MOBILE_PREVIEW_TABS.length;
 const next=event.key==='Home'?0:event.key==='End'?length-1:(index+(event.key==='ArrowRight'?1:-1)+length)%length;
 switchMobilePreview(MOBILE_PREVIEW_TABS[next][0],true);
});
function mobileLink(r,t,code){return '<button class="mobile-link '+(route===r?'active':'')+'" onclick="selectMobile(\''+r+'\')">'+icon('phone')+'<span class="flex1">'+t+'</span><span class="tiny muted">'+code+'</span></button>'}
function selectMobile(r){if(r==='mobile-approval'){let c=state.cases.find(c=>c.status==='待审批');if(c)activeId=c.id}if(r==='mobile-adjustment'){let c=state.cases.find(c=>c.status==='待财务确认');if(c)activeId=c.id}go(r)}
function phone(title,content,back='mobile-approvals'){return '<div class="phone"><div class="phone-notch"></div><div class="phone-status"><span>9:41</span><span>▮▮▮　 Wi-Fi　▰</span></div><div class="phone-nav"><button class="icon-btn" onclick="go(\''+back+'\')" aria-label="返回">'+icon('left')+'</button>'+title+'<span style="margin-left:auto;color:#9ba4b4">···</span></div><div class="phone-body">'+content+'</div><div class="phone-bottom"></div></div>'}
function mobilePage(){if(route==='mobile-new'){if(!flowSource()&&!newForm.editingId)newForm.sourceId=cxSources().find(x=>x.merge===current().merge&&x.sub===current().sub)?.id||cxSources()[0]?.id;return '<div class="ap-mobile-stage">'+newPage()+'</div>';}let title,code,content;let c=current();if(route==='mobile-approvals'){title='纠错待审核';code='P-AP-01';let rows=state.cases.filter(x=>x.status==='待审批'&&(mobileFilter==='全部'||(mobileFilter==='高风险')===x.high));content='<div class="spread gap-bottom"><div><h2>待核实申请</h2><p class="tiny muted">'+rows.length+' 项待处理申请</p></div>'+select(['全部','高风险','普通'],mobileFilter,'aria-label="移动端风险筛选" onchange="mobileFilter=this.value;render()"')+'</div>'+rows.map(x=>'<div class="mobile-card" role="button" tabindex="0" onclick="go(\'mobile-approval\',\''+x.id+'\')" onkeydown="if(event.key===\'Enter\')this.click()"><div class="spread"><span class="mono">'+x.id+'</span>'+badge(x.high?'高风险':'普通',x.high?'red':'green')+'</div><p class="small" style="margin:12px 0">'+x.reason+'</p><div class="spread small"><span class="muted">主档案 '+x.name+'</span><strong>'+money(x.amount)+'</strong></div><hr class="light-divider" style="margin:12px 0"><div class="spread tiny muted"><span>'+x.author+' · '+x.store+'</span><span>'+x.date.slice(5,16)+' →</span></div></div>').join('')+(!rows.length?empty('暂无待审核工单','所有待办已处理完成。'):'');content=phone('纠错待审核',content)}else if(route==='mobile-approval'){title='申请核实详情';code='P-AP-02';content=phone('纠错审批','<div class="spread gap-bottom"><span class="mono">'+c.id+'</span>'+badge(c.high?'高风险':'普通',c.high?'red':'green')+'</div>'+panel('申请信息',body(kv({'纠错原因':c.reason,'发起人':c.author,'详细说明':esc(c.description)})+'<div style="margin-top:10px">'+btn('查看 '+c.evidence.length+' 份附件','evidenceModal()','text','file')+'</div>'))+panel('档案对比',body('<div class="grid2"><div class="muted-card"><p class="tiny muted">原子档案</p><h3>'+c.subname+'</h3><p class="tiny muted">139****5678<br>客服B</p></div><div class="muted-card"><p class="tiny muted">当前主档案</p><h3>'+c.name+'</h3><p class="tiny muted">138****1234<br>客服A</p></div></div>'+btn('查看完整对比 →','mobileCompare()','text')))+panel('影响预估',body(impact(c,true)))+panel('核实进度',body(approvalTrail()))+panel('核实申请',body(approvalButtons(true))))}else if(route==='mobile-adjustment'){title='纠错调整单确认';code='P-AP-03';content=phone('调整单确认','<div class="mono gap-bottom">ADJ-'+c.id.slice(3)+'</div>'+panel('财务差异',body(c.finance.filter(f=>f.amount!==0).map(f=>'<div class="spread small" style="margin-bottom:13px"><span>'+f.type+'</span><span><b>'+cxSign(-cxSigned(f))+'</b>　<b>'+cxSign(cxSigned(f))+'</b></span></div>').join('')+'<hr class="light-divider"><div class="spread small"><span>合计净影响</span><strong class="positive">¥0</strong></div>'))+panel('业绩调整',body(kv({'客服A':'纠错扣减 ¥0','客服B':'纠错补增 ¥0'})+'<p class="small positive" style="margin-top:15px">✓ 核对后不涉及提成调整</p>'))+btn('查看冲销明细 →',"modal('冲销明细',reversalMiniTable(current()),'',true)",'text')+(c.cross?notice('跨门店工单须记录双方业务确认后完成。','warn'):'')+panel('结果确认',body(financialActions()+(c.status==='已完成'?'':btn('确认结果并完成','confirmAdjustment()','primary wide')))),'ticket')}else if(route==='mobile-customer'){title='门店客户档案';code='P-MB-01';let inner=mobileCustomerTab==='基本信息'?panel('客户信息',body(kv({'客户编号':c.cus,'客户姓名':c.name,'手机号':'138****1234','归属客服':'客服A','客户类型':'老客'}))):mobileCustomerTab==='订单'?panel('客户订单',body(['ORD-201 · 已完成 · ¥8,000','ORD-202 · 已排客 · ¥5,000','ORD-301 · 已完成 · ¥8,000','ORD-401 · 已排客 · ¥3,000'].map(t=>'<div class="small" style="padding:12px 0;border-bottom:1px solid var(--line)">'+t+'</div>').join(''))):mobileHistory();content=phone('客户档案','<div class="customer-row gap-bottom"><div class="avatar">'+c.name[0]+'</div><div><h2>'+c.name+'</h2><p class="tiny muted">'+c.cus+' · 138****1234</p></div></div><div class="panel"><div class="tabs">'+['基本信息','订单','合并历史'].map(t=>'<button class="tab '+(mobileCustomerTab===t?'active':'')+'" onclick="mobileCustomerTab=\''+t+'\';render()">'+t+'</button>').join('')+'</div></div>'+inner,'mobile-customer')}else{title='发起纠错';code='P-MB-02';content=phone('发起纠错',panel('关联合并记录',body(kv({'合并记录':c.merge,'主档案':c.name+' · '+c.cus,'原子档案':c.subname+' · '+c.sub})))+panel('纠错申请',body(applicationForm(true)))+panel('系统预估影响',body('<div class="spread"><span class="small">涉及金额</span><strong>'+money(c.amount)+'</strong></div><div style="margin-top:12px">'+badge(c.high?'高风险':'普通',c.high?'red':'green')+'</div>'))+btn('提交纠错申请','submitApplication(true)','primary wide'),'mobile-customer')};return '<div class="ap-mobile-stage">'+content+'</div>'}
function mobileCompare(){modal('档案完整对比',table(['数据项','原子档案（快照）','当前主档案'],[['姓名',current().subname,current().name],['手机号','139****5678','138****1234 / 139****5678'],['归属客服','客服B','客服A'],['订单','1笔已完成 · ¥8,000','4笔，含新增1笔'],['白条余额','¥2,000','¥4,500'],['加微记录','客服B · 03-01','客服A / 客服B']]),'',true)}
function mobileHistory(){let c=current();return panel('合并历史',body('<div class="mono">'+c.merge+'</div><p class="tiny muted" style="margin:9px 0">2026-09-01 · 自动合并<br>合并了 '+c.sub+' · '+c.subname+'</p>'+badge(c.status==='已完成'?'已纠错':'已合并',c.status==='已完成'?'green':'blue')+'<div class="actions" style="margin-top:14px">'+btn('查看详情',"modal('合并记录详情',sourceInfo())",'small')+(c.status==='已完成'?btn('查看纠错记录',"go('ticket')",'small'):btn('合并纠错',"go('mobile-new')",'primary small'))+'</div>'))+panel('最近合并 · 冷静期内',body('<div class="mono">MG-20261015-088</div><p class="tiny muted" style="margin:9px 0">今天 09:00 · 尚未发生后续业务</p>'+badge(c.coldCancelled?'已撤销':'冷静期中',c.coldCancelled?'green':'orange')+'<p class="tiny muted" style="margin-top:12px">冷静期结束前使用一键撤销。</p>'+(c.coldCancelled?'':btn('一键撤销','undoCooling()','small'))))+panel('历史归档记录',body('<div class="mono">MG-20250501-026</div><p class="tiny muted" style="margin:9px 0">超过12个月 · 快照已归档</p>'+btn('手工调账说明','archivedFlow()','text')))}
function apMobileTicket({o,kind}){
 const status=apStatus(o,kind),ended=['已合并','已完成','已驳回'].includes(status),nodes=apProcessNodes(o,kind),current=nodes.find(n=>['current','failed','rejected'].includes(n.status)),r=o.review;
 const plan=r?.approvedPlan||r?.submittedPlan||o.plan,customer=kind==='merge'?o.pair.find(c=>c.id===plan?.mainId)||o.pair[0]:o.correctionData?.current||{name:o.name};
 const lastReview=r?.events?.findLast(e=>/审核通过|加签通过|驳回|确认调整单/.test(e.action)),actor=ended?lastReview?.actor||o.approvedBy||o.completedBy||r?.assignee||'未记录':current?.actor||apReviewer(o);
 const tone=['已合并','已完成'].includes(status)?'green':['已驳回','执行失败'].includes(status)?'red':status.includes('财务')||status.includes('确认')?'orange':'blue';
 const tag=(label,color)=>'<span class="pill '+color+'">'+esc(label)+'</span>',tags=[kind==='merge'?tag(o.source||'合并申请',o.source==='系统拦截'?'orange':'blue'):tag(o.high?'高风险':'普通纠错',o.high?'orange':'green')];
 if(r?.urgency==='紧急')tags.push(tag('紧急','red'));
 const submittedAt=r?.submittedAt||o.time||o.date||'';
 return `<article class="ap-ticket-card ${ended?'is-ended':''}" role="button" tabindex="0" aria-label="查看${esc(apTitle(o,kind))}审核详情" onclick="${esc(`apOpen('${kind}',${mrQuote(o.id)})`)}" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();this.click()}">
  <div class="ap-ticket-heading"><span class="ap-ticket-no">${kind==='merge'?'合并':'纠错'}工单 ${uiId(o.id)}</span><span class="ap-ticket-state ${tone}">${esc(status)}</span></div>
  <h2>${esc(apTitle(o,kind))}</h2>
  <div class="ap-ticket-customer"><span>${esc(customer?.name||o.name)}</span><span>${esc(o.store)}</span></div>
  <div class="ap-ticket-meta"><span class="ap-ticket-badges">${tags.join('')}</span>${!ended?'<span class="ap-ticket-node">'+esc(current?.title||status)+'</span>':''}</div>
  <div class="ap-ticket-footer"><span class="ap-ticket-assignee"><span>${ended?'审核人':'办理人'}</span><b>${esc(actor)}</b></span><span class="ap-ticket-time" title="${esc('提交时间：'+submittedAt)}">提交 <time>${esc(submittedAt.slice(5,16))}</time></span></div>
 </article>`;
}
function apMobileToolIcon(name){return '<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="'+(name==='filter'?'M3 5h18l-7 8v6l-4 2v-8z':'M20 20l-5-5 M17 10a7 7 0 1 0-14 0 7 7 0 0 0 14 0')+'"/></svg>'}
function apMobileList(){
 let all=apRows(),rows=all.slice(0,apPage*8),f=apApplied[apView]||{},count=Object.entries(f).filter(([k,v])=>k!=='q'&&v).length,narrowed=Object.values(f).some(Boolean);
 return '<section class="ap-mobile-query">'+apTabs([['merge','合并审核'],['correction','纠错审核'],['history','审核记录']],apView,k=>`apSwitch('${k}')`)+`
 <form id="apMobileSearch" class="ap-mobile-search" role="search" onsubmit="event.preventDefault();apSearch()"><div class="ap-mobile-search-box"><button type="submit" aria-label="查询工单">${apMobileToolIcon('search')}</button><input type="search" enterkeyhint="search" aria-label="搜索审核工单" placeholder="工单号、客户或手机号" value="${esc(apFilter().q)}" oninput="apFilter().q=this.value"></div><button type="button" class="ap-mobile-filter ${count?'is-active':''}" aria-label="筛选工单${count?'，已选 '+count+' 项':''}" onclick="apMobileFilters()">${apMobileToolIcon('filter')}<span>${count?'已筛选':'筛选'}</span></button>${narrowed?'<button type="button" class="ap-mobile-reset" aria-label="重置搜索和筛选" onclick="apReset()">重置</button>':''}</form></section>
 <div class="ap-mobile-list">${rows.map(apMobileTicket).join('')||'<div class="ap-empty">暂无符合条件的工单<br>可调整筛选条件后重试</div>'}
 <div class="ap-load-more">${rows.length<all.length?btn('加载更多','apTurn(1)','text'):all.length?'已显示全部工单':''}</div></div>`;
}
function apMobileFilters(){let f=clone(apFilter()),stores=[...new Set(apAll().flatMap(x=>x.kind==='merge'?x.o.pair.map(c=>c.store):[x.o.store]))],reasons=[...new Set(state.mergeApplications.flatMap(a=>a.reasons||[]))],control=(label,key,options)=>field(label,select(options,f[key],`aria-label="${label}" onchange="apSheet.filter.${key}=this.value"`)),html=control('门店','store',[['','全部门店'],...stores])+(apView==='merge'?control('拦截原因','reason',[['','全部拦截原因'],...reasons])+control('紧急程度','urgency',[['','全部紧急程度'],'普通','紧急']):'')+control('审核结果','status',[['',apView==='history'?'全部审核结果':'待处理'],['all','全部状态'],'待审核','待财务加签','待调整单确认','已驳回','已合并','已完成','执行失败']);if(apView==='history')html+=field('开始日期',`<input type="date" value="${esc(f.from)}" aria-label="审核开始日期" onchange="apSheet.filter.from=this.value">`)+field('结束日期',`<input type="date" value="${esc(f.to)}" aria-label="审核结束日期" onchange="apSheet.filter.to=this.value">`);apPrompt('筛选工单',html,btn('重置','apFilterClear()')+btn('确定','apFilterApply()','primary'));apSheet.filter=f}
function apMobileOverview(o){
 if(apTask.kind==='correction')o=apCorrectionView(o);
 let r=o.review,kind=apTask.kind,nodes=apProcessNodes(o),current=nodes.find(n=>['current','failed','rejected'].includes(n.status)),ended=kind==='merge'?!!o.recordId:o.status==='已完成',person=kind==='merge'?o.pair.find(c=>c.id===apMergePlan(o).mainId)||o.pair[0]:o.correctionData?.current||{name:o.name,phone:o.phone},profileAction=kind==='merge'?'customers':'snapshot';
 let info=apFacts([['客户',`<span class="ap-info-customer">${esc(person.name)} <span>${esc(uiPhone(person.phone))}</span>${btn('客户资料',kind==='merge'?"apMobileTab('customers')":`apMobilePanel('${profileAction}')`,'text')}</span>`],['所属门店',esc(o.store)]]),more=apFacts([['申请人',esc(r?.submittedBy||o.author)],['提交时间',esc(r?.submittedAt||o.time||o.date)],['工单来源',esc(o.source||'门店纠错申请')],['参与档案',kind==='merge'?o.pair.map(c=>esc(c.name)+' · '+uiId(c.id)).join('、'):'合并记录 '+uiId(o.merge)]]);
 if(kind==='merge'){info+=apFacts([['申请原因',esc(o.reasonType||'未填写原因分类')]]);more+=apFacts([['触发场景',esc(o.trigger||'未记录')],['检测线索',esc(o.match||'人工选择档案')],['采用规则',esc(o.rule.name)+' V'+esc(o.rule.version)],['资料时点',esc(r?.submittedAt||o.time)+' · 提交时快照']])}

 return `<section class="ap-overview"><div class="ap-overview-heading"><h2>工单信息</h2>${apBadge(apStatus(o,kind))}</div><h1>${esc(apTitle(o,kind))}</h1><div class="ap-identifiers">工单 ${uiId(o.id)} ${o.high?badge('高风险','orange'):esc(r?.urgency||'普通')}</div><div class="ap-current-task"><div class="ap-current-task-row"><div><span>${ended?'办理结果':'当前环节'}</span><strong>${esc(ended?'已办结':current?.title||apStatus(o,kind))}</strong></div><div><span>${ended?'完成处理人':'当前办理人'}</span><strong>${esc(ended?o.completedBy||'系统':current?.actor||apReviewer(o))}</strong></div></div><p class="ap-current-task-foot">${esc(ended?'处理结果与操作记录可追溯':current?.note||'等待处理')}</p></div>${o.reasons?.length?'<p class="ap-intercept-note">'+icon('shield')+esc(o.reasons.join('；'))+'</p>':''}${info}<div class="ap-application-reason"><span>申请内容</span><p>${esc(o.description||o.reason||'前置规则拦截，需人工核对合并方案')}</p></div><details class="ap-more-info" ${apTask.infoExpanded?'open':''} ontoggle="if(apTask&&this.isConnected)apTask.infoExpanded=this.open"><summary>更多工单信息</summary><div>${more}</div></details></section>`;
}
function apMobileReviewTabs(){return apTask.kind==='merge'?[['plan','方案概览'],['customers','档案对比'],['orders','订单方案'],['impact','影响明细']]:[['plan','方案概览'],['business','业务调整'],['impact','影响核对'],...(apObj().resultData?[['result','执行结果']]:[])]}
function apMobileTab(tab){if(!apTask)return;if(tab==='logs'){apShowRecords();return}if(!apMobileReviewTabs().some(([key])=>key===tab))return;apTask.mobileTab=tab;let scroller=$('.ap-mobile-scroll'),workspace=$('.ap-workspace'),pinned=scroller&&workspace&&workspace.getBoundingClientRect().top<=scroller.getBoundingClientRect().top+1;render();if(pinned){scroller=$('.ap-mobile-scroll');workspace=$('.ap-workspace');scroller.scrollTop+=workspace.getBoundingClientRect().top-scroller.getBoundingClientRect().top}$('.ap-workspace>.ap-tabs [aria-selected="true"]')?.focus({preventScroll:true})}
function apMobileContent(){let o=apObj(),tab=apTask.mobileTab;if(tab==='plan'||tab==='logs')return apMobilePlan(o);let html=apTask.kind==='merge'?(tab==='customers'?apCustomerCompare(o):tab==='orders'?apMobileMergeOrders(o):tab==='impact'?apMergeImpact(o):''):(tab==='business'?apCorrectionBusiness(o):tab==='impact'?apCorrectionImpact(o):tab==='result'?apCorrectionResult(o):'');return '<section class="ap-detail-card">'+apMobileMarkup(html)+'</section>'}
function apMobileProcess(o){let nodes=apProcessNodes(o),labels={done:'已完成',current:'办理中',future:'未开始',unknown:'未记录',rejected:'已驳回',failed:'执行失败'};return '<section class="ap-process-card ap-detail-card" aria-labelledby="ap-process-title"><h3 id="ap-process-title">处理流程</h3><ol class="ap-process-list">'+nodes.map((n,i)=>`<li class="ap-process-node is-${n.status}" ${n.status==='current'?'aria-current="step"':''}><span class="ap-process-marker" aria-hidden="true">${n.status==='done'?icon('check'):n.status==='current'?icon('clock'):i+1}</span><div class="ap-process-body"><div class="ap-process-heading"><h4>${esc(n.title)}</h4><span>${labels[n.status]}</span></div><p class="ap-process-person"><span>${n.status==='current'?'当前办理人':'处理人'}</span>${esc(n.actor)}</p>${n.at?'<time>'+esc(n.at)+'</time>':''}${n.note?'<p class="ap-process-note">'+esc(n.note)+'</p>':''}</div></li>`).join('')+'</ol></section>'}
function apMobileMergeOverview(o){
 const v=apMergeReview(o),status=o.review?.status==='approved'?'已通过方案':o.review?.status==='rejected'?'已驳回方案':'已提交方案';
 const supplements=o.manualRequests?.length?'<section class="ap-plan-read-section"><h4>补充申请</h4>'+o.manualRequests.map(x=>apFacts([['申请人 / 时间',esc(x.author)+' · '+esc(x.time)],['补充说明',esc(x.reason||'未填写')]])).join('')+'<p class="ap-plan-note">补充申请仅供参考，不替换本次提交方案。</p></section>':'';
 return '<section class="ap-plan-card ap-detail-card"><div class="ap-plan-heading"><h3>本次合并方案</h3><span>'+status+'</span></div>'+apFacts(apMergeKeyFacts(v))+'<p class="ap-plan-note">按已提交方案审核；方案不符请驳回，由申请人修改后重新提交。</p>'+supplements+'</section>'+apMobileProcess(o)+apMobileRecords(o);
}
function apMobilePlan(o){return apTask.kind==='merge'?apMobileMergeOverview(o):apCorrectionOverview(o,true)}
function apMobileRecords(o){let rows=apOperationEntries(o);return '<section class="ap-operation-card ap-detail-card"><h3>操作记录</h3>'+(rows.length?'<ol class="ap-operation-list">'+rows.map((e,i)=>`<li class="ap-operation-event ${i===0?'is-latest':''}"><h4>${esc(e.title)} <span>· ${esc(e.actor)}</span></h4>${e.at?'<time>'+esc(e.at)+'</time>':''}${e.note?'<p>'+esc(e.note)+'</p>':''}</li>`).join('')+'</ol>':'<p class="ap-plan-note">此历史工单未保存操作记录。</p>')+'</section>'}
function apMobilePanelContent(key){let o=apObj();if(key==='customers')return apCustomerCompare(o);if(key==='orders')return apMobileMergeOrders(o);if(key==='mergeOrder')return apMobileOrderDetails(o);if(key==='impact')return apTask.kind==='merge'?apMergeImpact(o):apCorrectionImpact(o);if(key==='correction')return apCorrectionBusiness(o);if(key==='snapshot')return apCorrectionSource(apCorrectionView(o));if(key==='result')return apCorrectionResult(o);return ''}
function apMobilePanel(key){if(!apTask||!['customers','orders','impact','correction','snapshot','result'].includes(key))return;let title={customers:'客户资料与主档案',orders:'进行中订单处理',impact:'业务与财务影响',correction:'完整纠错方案',snapshot:'快照与当前档案对比',result:'纠错调整单'}[key];apSheet={title,panel:key,content:'',footer:btn('返回详情','apDismiss()','primary'),returnAction:document.activeElement?.getAttribute('onclick')};apRenderSheet()}
function apMobileMergeOrders(a){
 const v=apMergeReview(a),rows=a.pair.flatMap(c=>(c.orders||[]).map(o=>({c,o,info:maOrderInfo(c,o)}))),active=rows.filter(x=>mrActive(x.o)),history=rows.filter(x=>!mrActive(x.o));
 const summary='<p class="ap-order-summary"><span>保留 <b>'+(v.active.length-v.impact.returned.length)+'</b> 笔</span><span>合并流退 <b>'+v.impact.returned.length+'</b> 笔</span>'+(v.impact.cancelled.length?'<span>取消排客 <b>'+v.impact.cancelled.length+'</b> 笔</span>':'')+'</p>';
 const date=value=>String(value||'').replace('T',' ').replace(/(\d{2}:\d{2}):\d{2}$/,'$1');
 const card=({c,o,info},isHistory=false)=>{
  const returned=v.impact.returned.some(x=>x.id===o.id),cancelled=v.impact.cancelled.some(x=>x.id===o.id),action=isHistory?'原终态保留':returned?'合并流退':'保留订单';
  const people=[info.bookingBy?'预约 '+info.bookingBy:'',info.receiver?'接待 '+info.receiver:''].filter(Boolean);
  const appointment=info.appointment?'预约 '+date(info.appointment):o.status==='待排客'?'尚未排客':'';
  const effect=returned?(cancelled?'取消排客 · '+(date(info.appointment)||'预约时间未记录'):o.status==='已到店'?'订单转为已流退，实际到店记录保留':'订单转为已流退'):'';
  const details=btn('订单资料',`apMobileOrder(${mrQuote(c.id)},${mrQuote(o.id)})`,'text');
  return '<article class="ap-order-item'+(isHistory?' is-history':'')+'" data-order-id="'+esc(o.id)+'"><div class="ap-order-title"><h4>'+esc(info.name)+'</h4><span class="ap-order-action '+(isHistory?'is-history':returned?'is-returned':'is-kept')+'">'+action+'</span></div>'+
   '<p class="ap-order-source">订单 '+uiId(o.id)+' · '+esc(c.name)+' '+uiId(c.id)+' · '+esc(o.status)+'</p>'+
   (effect?'<p class="ap-order-effect">'+esc(effect)+'</p>':'')+
   (!isHistory?'<div class="ap-order-context">'+(appointment||info.store?'<p>'+[appointment,info.store].filter(Boolean).map(esc).join(' · ')+'</p>':'')+(people.length?'<p>'+people.map(esc).join(' · ')+'</p>':'')+'</div>':'')+
   '<div class="ap-order-bottom"><span>'+(isHistory?'':(o.amount==null?'订单金额未记录':'订单 '+money(o.amount))+(o.deposit==null?'':' · 预约金 '+money(o.deposit)))+'</span>'+details+'</div></article>';
 };
 return apSection('进行中订单',summary+(active.length?'<div class="ap-order-items">'+active.map(x=>card(x)).join('')+'</div>':'<p class="ap-plan-note">无进行中订单。</p>')+(v.impact.returned.length?'<p class="ap-plan-note">流退订单的原收款保留，本次合并不自动退款。</p>':''))+(history.length?apSection('历史订单','<p class="ap-order-history-note">按原终态保留，随档案合并。</p><div class="ap-order-items">'+history.map(x=>card(x,true)).join('')+'</div>'):'');
}
function apMobileOrder(customerId,orderId){
 if(!apTask||apTask.kind!=='merge'||!apIsMobile())return;
 const c=apObj().pair.find(x=>x.id===customerId),o=c?.orders?.find(x=>x.id===orderId);if(!o)return;
 const parent=apSheet?{...apSheet,scroll:$('#apMobileSheet .ap-action-body')?.scrollTop||0}:null;
 apSheet={title:'订单资料',panel:'mergeOrder',customerId,orderId,parent,footer:btn('返回订单方案','apDismiss()','primary'),returnAction:document.activeElement?.getAttribute('onclick')};apRenderSheet();$('#apMobileSheet .ap-action-body').scrollTop=0;
}
function apMobileOrderDetails(a){
 const c=a.pair.find(x=>x.id===apSheet.customerId),o=c?.orders?.find(x=>x.id===apSheet.orderId);if(!o)return '<p class="ap-plan-note">订单资料不存在。</p>';
 const v=apMergeReview(a),info=maOrderInfo(c,o),active=mrActive(o),returned=v.impact.returned.some(x=>x.id===o.id),payments=(c.payments||[]).filter(x=>x.orderId===o.id),reason=v.submitted.orderReasons?.[o.id];
 return apSection('订单与处理',apFacts([['订单',esc(info.name)+' · '+uiId(o.id)],['来源档案',esc(v.label(c))],['提交时状态',esc(o.status)],['合并处理',active?returned?'合并流退':'保留订单':'历史订单保留'],...(returned?[['处理影响',esc(apMergeOrderEffect(v,o))]]:[]),...(reason?[['处理依据',esc(reason)]]:[])]))+
 apSection('预约与人员',apFacts([['订单门店',esc(info.store||'未记录')],['预约时间',esc(info.appointment||'未安排')],['预约人员',esc(info.bookingBy||'未记录')],['接待人员',esc(info.receiver||'未记录')],['订单客服',esc(o.consultant||'未记录')],['创建时间',esc(info.created||'未记录')],['到店时间',esc(info.arrived||'未记录')]]))+
 apSection('金额与支付',apFacts([['订单金额',o.amount==null?'未记录':money(o.amount)],['预约金',o.deposit==null?'未记录':money(o.deposit)],['预约金支付',esc(info.paid||'未记录')],['关联收退款',Array.isArray(c.payments)?payments.length+' 笔 · 净额 '+money(payments.reduce((s,x)=>s+pcPaymentAmount(x),0)):'独立支付流水未保存']])+(payments.length?table(['流水','类型 / 时间','金额'],payments.map(x=>[uiId(x.id),esc(x.type)+'<div class="tiny muted">'+esc(x.at||'时间未记录')+'</div>',cxSign(pcPaymentAmount(x))])):''));
}
function apMobileMarkup(html){let tpl=document.createElement('template');tpl.innerHTML=html;tpl.content.querySelectorAll('table').forEach(t=>{let heads=[...t.querySelectorAll('thead th')].map(h=>h.textContent),out=document.createElement('div');out.className='ap-data-list';for(let tr of t.querySelectorAll('tbody tr')){let card=document.createElement('article');card.className='ap-data-card';[...tr.children].forEach((td,i)=>{let line=document.createElement('div');line.className='ap-data-line';let label=document.createElement('span');label.className='ap-data-label';label.textContent=heads[i]||'详情';let value=document.createElement('div');value.className='ap-data-value';while(td.firstChild)value.append(td.firstChild);line.append(label,value);card.append(line)});out.append(card)}if(!out.children.length)out.innerHTML='<p class="ap-empty">无相关记录</p>';t.replaceWith(out)});return tpl.innerHTML}
function apMobilePage(){let o=apObj(),title=apTask?(apTask.kind==='merge'?'合并审核详情':'纠错审核详情'):'审核工作台',content=apTask?'<div class="ap-detail-content">'+apMobileOverview(o)+'<section class="ap-workspace ap-merge-workspace">'+apTabs(apMobileReviewTabs(),apTask.mobileTab,k=>`apMobileTab('${k}')`)+'<div class="ap-workspace-content" role="tabpanel" aria-label="'+(apMobileReviewTabs().find(([key])=>key===apTask.mobileTab)?.[1]||'方案概览')+'">'+apMobileContent()+'</div></section></div>':apMobileList();return `<div class="ap-mobile-stage"><section class="ap-mobile-shell" aria-label="${title}"><div class="ap-device-status" aria-hidden="true"><span>9:41</span><i></i><span>▮▮▮　Wi-Fi　▰</span></div><header class="ap-mobile-header">${apTask?'<button class="ap-back" aria-label="返回审核列表" onclick="apMobileBack()">'+icon('left')+'返回</button>':'<span></span>'}<h2>${title}</h2><span></span></header><div class="ap-mobile-scroll">${content}</div>${apTask?'<footer class="ap-mobile-footer">'+apFooter()+'</footer>':''}<div class="ap-device-bottom" aria-hidden="true"><i></i></div><div id="apMobileSheet"></div></section></div>`}
function apMobileBack(){if(apSheet){apDismiss();return}if(apTask)apClose();else{apView='merge';render()}}
function apRenderMobile(){let scroll=$('.ap-mobile-scroll')?.scrollTop||0,key=apTask?apTask.id:apView;if(apSheet&&$('#apMobileSheet .ap-action-body')){apSheet.scroll=$('#apMobileSheet .ap-action-body').scrollTop;apSheet.focusLabel=$('#apMobileSheet')?.contains(document.activeElement)?document.activeElement.getAttribute('aria-label'):null}nav();document.body.classList.toggle('approval-h5',new URLSearchParams(location.search).get('view')==='h5');$('#main').innerHTML=mobilePreviewTabs()+apMobilePage();$('#mergeDrawers').innerHTML='';$('#modal').innerHTML='';syncDrawerInteraction();if(apRenderMobile.key===key)$('.ap-mobile-scroll').scrollTop=scroll;apRenderMobile.key=key;apRenderSheet();uiNormalizeIds();restoreMobilePreviewFocus();document.title='审核管理端 · WEID微动'}
function apRenderSheet(){let root=$('#apMobileSheet');if(!root)return;for(let el of $$('.ap-mobile-shell>.ap-mobile-scroll,.ap-mobile-shell>.ap-mobile-header,.ap-mobile-shell>.ap-mobile-footer'))el.inert=!!apSheet;if(!apSheet){root.innerHTML='';return}let oldBody=root.querySelector('.ap-action-body'),scroll=oldBody?.scrollTop??apSheet.scroll??0,focus=document.activeElement,focusLabel=root.contains(focus)?focus.getAttribute('aria-label'):apSheet.focusLabel,content=apSheet.panel?apMobileMarkup(apMobilePanelContent(apSheet.panel)):apSheet.content;root.innerHTML='<section class="ap-action-page" role="dialog" aria-modal="true" aria-label="'+esc(apSheet.title)+'"><header class="ap-mobile-header"><button class="ap-back" onclick="apDismiss()" aria-label="返回上一页">'+icon('left')+'返回</button><h2>'+esc(apSheet.title)+'</h2><span></span></header><div class="ap-action-body">'+content+'</div><footer class="ap-action-footer"><p class="ap-action-error" role="alert" hidden></p><div>'+apSheet.footer+'</div></footer></section>';root.querySelector('.ap-action-body').scrollTop=scroll;delete apSheet.scroll;delete apSheet.focusLabel;if(focusLabel)[...root.querySelectorAll('[aria-label]')].find(x=>x.getAttribute('aria-label')===focusLabel)?.focus({preventScroll:true});else root.querySelector('button')?.focus({preventScroll:true});}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&window.PCUI?.isPopupOpen())return;if(!apIsMobile()||!apSheet)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();apDismiss()}else if(e.key==='Tab'){let items=[...document.querySelectorAll('#apMobileSheet button,#apMobileSheet textarea,#apMobileSheet select,#apMobileSheet input')].filter(x=>!x.disabled&&x.getClientRects().length),first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}},true);
